static xBaseAsset DispatcherDefaultsInit()
{
    xBaseAsset a;
    memset(&a, 0, sizeof(a));
    a.baseType = eBaseTypeDispatcher;
    a.baseFlags = 0xD;
    return a;
}

static const xBaseAsset kDispatcherDefaults = DispatcherDefaultsInit();

void MNU4_BuildDispatcher(iAssetPkg& p)
{
    {
        xBaseAsset a = kDispatcherDefaults;
        p.Begin('DPAT', H("PAUSE STATE DISP"), a);
        p.Link(eEventDispatcher_PauseState_Pause, eEventUIFocusOn, H("PAUSE GROUP"));
        p.Link(eEventDispatcher_PauseState_Pause, eEventUISelect, H("PAUSE MGR UIF"));
        p.Link(eEventDispatcher_GameState_Play, eEventUIFocusOff_Unselect, H("PAUSE GROUP"));
        p.Link(eEventDispatcher_GameState_Play, eEventInvisible, H("PAUSE GROUP"));
        p.Link(eEventDispatcher_GameState_Play, eEventInvisible, H("PAUSE BKG GROUP"));
        p.Link(eEventDispatcher_PauseState_Pause, eEventPlay, H("MNU4 AMBIENT SFX"));
        p.Link(eEventDispatcher_GameState_Play, eEventStop, H("MNU4 AMBIENT SFX"));
        p.Link(eEventDispatcher_GameState_Play, eEventUIFocusOff_Unselect, H("LEVEL BUBBLE GROUP"));
        p.Link(eEventDispatcher_GameState_Play, eEventInvisible, H("LEVEL BUBBLE GROUP"));
        p.Link(eEventDispatcher_GameState_Play, eEventInvisible, H("PAUSE OPTIONS BKG GROUP"));
        p.Link(eEventDispatcher_GameState_Play, eEventInvisible, H("TASK SPATULA ALL GROUP"));
        p.Link(eEventDispatcher_GameState_Play, eEventUIFocusOff_Unselect, H("TASK SPATULA ALL GROUP"));
        p.Link(eEventDispatcher_PauseState_Pause, eEventRun, H("PAUSE_TIMER44"));
        p.Link(eEventDispatcher_GameState_Play, eEventInvisible, H("GAME PAUSED GROUP"));
        p.Link(eEventDispatcher_GameState_Play, eEventExpired, H("GAME PAUSED GROUP"));
        p.Link(eEventDispatcher_GameState_Play, eEventInvisible, H("UI HIDE LEFTOVERS GROUP"));
        p.Link(eEventDispatcher_GameState_Play, eEventInvisible, H("UI HIDE LEFTOVERS GROUP"));
        p.Link(eEventDispatcher_GameState_Play, eEventReset, H("PAUSE_TIMER45"));
        p.Link(eEventDispatcher_GameState_Play, eEventStop, H("TAXI CONFIRM TIMER GROUP"));
        p.End();
    }

    {
        xBaseAsset a = kDispatcherDefaults;
        p.Begin('DPAT', H("MNU4 CONTROLS DISP"), a);
        p.End();
    }

    {
        xBaseAsset a = kDispatcherDefaults;
        a.baseFlags = 0x1D;
        p.Begin('DPAT', H("SV DISPATCH"), a);
        p.End();
    }

    {
        xBaseAsset a = kDispatcherDefaults;
        a.baseFlags = 0x1D;
        p.Begin('DPAT', H("HUD TOGGLE DISP"), a);
        p.Link(eEventSceneBegin, eEventUIFocusOn_Select, H("HUD TOGGLE UIF"));
        p.End();
    }
}

