static xPortalAsset PortalDefaultsInit()
{
    xPortalAsset a;
    memset(&a, 0, sizeof(a));
    a.baseType = eBaseTypePortal;
    a.baseFlags = 0xD;
    a.assetCameraID = H("STARTCAM");
    a.assetMarkerID = 0x76E17D6E;
    a.sceneID = iAssetTag("SB10");
    return a;
}

static const xPortalAsset kPortalDefaults = PortalDefaultsInit();

void MNU4_BuildPortal(iAssetPkg& p)
{
    {
        xPortalAsset a = kPortalDefaults;
        p.Begin('PORT', H("EXIT LEVEL PORTAL"), a);
        p.End();
    }

    {
        xPortalAsset a = kPortalDefaults;
        a.assetCameraID = 0xACEF4597;
        a.assetMarkerID = H("FROM MNU4");
        a.sceneID = iAssetTag("SM40");
        p.Begin('PORT', H("WARP TO SM40"), a);
        p.End();
    }

    // The settings screen's widgets, shown and focused together.
    {
        xGroupAsset a = kGroupDefaults;
        a.baseFlags = 0x1D;
        p.Begin('GRUP', H(ISETTINGS_GROUP), a);
        p.Item(H(ISETTINGS_TITLE));
        for (S32 i = 0; i < ISETTINGS_ROWS; i++)
        {
            char name[32];
            sprintf(name, ISETTINGS_LABEL, (int)i);
            p.Item(H(name));
            sprintf(name, ISETTINGS_VALUE, (int)i);
            p.Item(H(name));
        }
        p.Item(H(ISETTINGS_HELP));
        p.End();
    }
}
